    question:
      "保険薬局に勤務している薬剤師が、看護学校の講師を担当することになった。講義では、植物に含まれている麻薬成分が医療用麻薬として使用されていることを紹介することにした。最近、高度のがん疼痛のある患者が、その初回の服薬を躊躇した事例を経験したことから、その場合の対応や、現場での医療用麻薬の有効な使い方についても講義しようと考えている。患者が服薬を躊躇した事例の処方薬は、モルヒネ塩酸塩水和物徐放性カプセルとモルヒネ塩酸塩水和物内用液であった。\n\n講義で伝える内容として、適切なのはどれか。2つ選べ。",

