      "この感染症は、抗菌薬使用後に問題となるClostridioides difficile感染症を想定する。C. difficileは芽胞を形成し、アルコールに抵抗性を示すため、手指衛生では消毒用エタノールよりも、クレゾール石けんなどと流水による物理的な洗浄が重要となる。また、環境中の芽胞対策として、便座などの消毒には次亜塩素酸ナトリウムが有効である。1は、主な対策としては便や汚染環境を介した接触感染への対応が重要で、「間接伝播」とだけするのは適切とはいえない。2は、芽胞は熱や一般的消毒に抵抗性があり、煮沸消毒で十分とは考えにくい。3は、エタノールが芽胞に無効なため誤り。"
