    "調製にはルアーロック型のシリンジを使用する。",
    "外径がより細い32Gの注射針を用いて調製する。",
    "飛散した薬液は安全キャビネット内で中心部から周囲に向かって拭き取る。",
    "薬液を拭き取った後は水を含ませたガーゼで拭き、さらに消毒用エタノールを含ませたガーゼで清拭する。"
