    "ヒスタミンH1受容体及びアドレナリンα1受容体を刺激することで、統合失調症の陰性症状を改善する。",
    "ドパミンD2受容体を遮断することで、統合失調症の陽性症状を改善する。",
    "γ-アミノ酪酸GABAA受容体のベンゾジアゼピン結合部位に結合することで、睡眠を誘発する。",
