    caseId: "110-246-247",
    caseContext:
      "30歳男性。以下の処方1～3が記載された処方箋を持って薬局を訪れた。この薬局では、1名の薬学生が実習中であった。\n\n（処方1）\nリスペリドン錠1 mg　1回1錠（1日3錠）\nスルピリド錠100 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食後　14日分\n\n（処方2）\nハロペリドール細粒1％　1回0.6 g（1日0.6 g）\n1日1回　朝食後　14日分\n\n（処方3）\nラメルテオン錠8 mg　1回1錠（1日1錠）\n1日1回　就寝前　14日分",
