    hasImage: true,
    image: "/pharmacy/110/practical/q247.png",

    question:
      "指導薬剤師は、実務実習生に下表の換算値を用いて経口抗精神病薬のクロルプロマジン換算量を算出する課題を出した。この患者の1日分のクロルプロマジン換算量はどれか。1つ選べ。\n\n（経口抗精神病薬の等価換算表）\n薬物：経口クロルプロマジン100 mgに相当する換算値\nクロルプロマジン：100\nスルピリド：200\nハロペリドール：2\nリスペリドン：1",

