    question:
      "29歳女性。5年前に潰瘍性大腸炎と診断され、メサラジン、副腎皮質ステロイド薬、タクロリムス、アザチオプリン、アダリムマブを使用してきたが、これまでの治療薬では寛解の維持が困難であった。医師はこれまでとは異なる作用機序の薬剤を新たに開始することを検討している。\n\n患者は内服薬による治療を希望し、新たに内服薬を開始することになった。医師より、開始する薬剤に関する留意点について、患者への説明を依頼された。説明する内容として適切なのはどれか。2つ選べ。",

