      "82歳男性。夜中に咳込みが激しくなり、病院を受診したところ、気管支ぜん息と診断され、処方1の薬剤が処方された。薬剤師は吸入練習機を用いて吸入指導を行い、薬剤を交付した。しかし、数日後、家族が薬局に来局し、「処方1の薬剤を吸入するとむせるようになり、吸入が困難になった」と話した。薬剤師が処方医にこの情報を提供したところ、再診察を行い処方1を処方2に変更した。\n\n（処方1）\nアニュイティ100 μg エリプタ30吸入用（注1） 1本\n1回2吸入　1日1回　朝　吸入\n注1：フルチカゾンフランカルボン酸エステルを含有するドライパウダー吸入器（DPI）。1吸入でフルチカゾンフランカルボン酸エステルとして100 μgを吸入できる。\n\n（処方2）\nオルベスコ100 μg インヘラー56吸入用（注2） 1本\n1回1吸入　1日1回　朝　吸入\n注2：シクレソニドを含有する加圧式定量噴霧器（pMDI）。1吸入でシクレソニドとして100 μgを吸入できる。",
