    "処方1の薬剤に用いられている容器は、薬剤を含むエアゾール缶、定量バルブとアクチュエーター等から構成される。",
    "処方2の薬剤は、吸入量が一定となるように調製された固体粒子のエアゾールとして吸入する。",
