    caseContext:
      "25歳女性。既婚。子供を欲しいと思っている。2ヶ月ほど前から屋外での作業の後、微熱、疲労感、関節痛及び両頬に紅斑が現れたため、市販の感冒薬と解熱鎮痛薬で様子を見ていた。3日前から38℃台の発熱と下肢の浮腫、冷たいものを持つと両手指のしびれ・蒼白現象などが出現したため、総合病院を受診したところ、精査目的で入院となった。血液検査結果は以下のとおりであった。（検査値）白血球2,800/μL、赤血球400×10^4/μL、血小板9.3×10^4/μL、血中総ビリルビン0.6 mg/dL、ALT 26 IU/L、AST 15 IU/L、BUN 45 mg/dL、血清クレアチニン2.0 mg/dL、抗核抗体640倍、抗Sm抗体8倍、尿タンパク（2＋）",
