    explanation:
      "正答は1、4です。\nデノスマブは骨転移などで用いられますが、低カルシウム血症を起こすことがあるため、血清Ca値の確認や症状の情報共有が重要です。\nまた、モルヒネは腎機能低下時に代謝物が蓄積しやすく、副作用が出やすくなることがあります。フェンタニル貼付剤は腎機能の影響を比較的受けにくいため、変更を検討する対応は適切です。\n2のゾレドロン酸は腎機能への注意が必要で、安易な変更は適切とはいえません。3のQT延長はモルヒネで特に注意すべき代表的副作用ではありません。5のロキソプロフェンはNSAIDsであり、強オピオイドの代替としてがん疼痛管理を行う選択肢としては不十分です。"
