    caseContext:
      "70歳女性。20年前に糖尿病と診断され、通院加療していたが、内服薬のみでのコントロールが困難となり、インスリン導入目的で入院となった。インスリンを使用し、血糖コントロールが良好となったため、まもなく退院できる見込みである。患者より、インスリン投与前に自己検査用グルコース測定器を用いて行う血糖自己測定について退院前に再度説明して欲しいとの訴えがあった。患者に困ったことはないか質問すると、穿刺後血液が少ししか出ないことや、「測定できません」と表示され再検査しなければならないことが多くて困るとのことであった。この患者が使用している自己検査用グルコース測定器の特徴：医療機器承認番号が付されている。高度管理医療機器である。特定保守管理医療機器である。形状等は図で示され、電源ボタン、メインパネル、チップ装着部がある。",
    field: "実務",

