      "50歳女性。身長155 cm、体重48 kg。B型肝炎の既往あり。起床時の手指関節のこわばり、肘関節、膝関節の痛みを主訴として受診し、関節リウマチと診断され、処方1と処方2の薬剤で治療していた。その後、炎症がコントロールできず、受診した際に注射薬の追加が提案されたが、患者から「自分で注射するのは怖い。病院内で点滴してほしい。」との要望があったため、処方3が追加されることとなった。なお、処方3の薬剤は、製造販売業者から卸売販売業者を経て、納入されたものである。\n\n（処方1）\nメトトレキサートカプセル2 mg　1回1カプセル（1日2カプセル）\n毎週　日曜日　1日2回　8時、20時　4日分（投与実日数）\n\n（処方2）\nメトトレキサートカプセル2 mg　1回1カプセル（1日1カプセル）\n毎週　月曜日　1日1回　8時　4日分（投与実日数）\n\n（処方3）\n点滴静注　アバタセプト（遺伝子組換え）点滴静注用\n（250 mg/バイアル　2本）　500 mg\n生理食塩液100 mL\n1日1回　30分かけて投与",
