    caseContext:
      "10歳男児。小学校では他の児童と比べ、忘れ物が多く、授業中も落ち着きがなく集中力が続かないと担任から指摘され、専門医を受診したところ、注意欠陥・多動性障害（ADHD）と診断された。環境調整や保護者への支援などを行ったが効果が不十分なため、以下の薬剤が開始されることになった。\n\n（処方）\nメチルフェニデート塩酸塩徐放錠18 mg　1回1錠（1日1錠）\n1日1回　朝食後　14日分",
