    caseContext:
      "79歳男性。難治性の気管支ぜん息と診断され、吸入ステロイド薬及び長時間作用性気管支拡張薬による吸入療法を行っていた。しかし、効果不十分のため3ヶ月前よりメポリズマブ（遺伝子組換え）皮下注が追加され、院内処方にて病院で使用法の指導・確認を行っていた。今月より院外処方となり、薬局に処方1の処方箋を持って訪れた。薬剤師は、患者に練習用模擬ペンにて一連の操作をしてもらい、適切に使用できるか確認することとした。なお、この男性は、同一世帯に75歳の妻がおり、両者とも要支援・要介護認定は受けていない。この夫婦は年金受給者でその他の収入はなく、窓口負担割合が1割である。\n\n（処方1：処方日 7月1日）\nメポリズマブ（遺伝子組換え）皮下注（100 mg/1キット）（注） 1キット\n1回100 mg\n4週間に1回　皮下注射（自己注射）\n（注）この薬剤1キットの薬価は約16万円である。\n\n皮下注ペンの構造と概要：薬液確認バー、針キャップ（透明）、安全カバー、薬液確認窓がある。未使用の場合、薬液確認窓から薬液が見える。薬液注入後、薬液確認バーが左側に移動する。穿刺用針は安全カバーに内蔵されており、針キャップを外し、安全カバーが見えなくなるまで穿刺部位にペン先を押し込むと、針が刺さり、薬液が注入される構造となっている。",
    field: "法規",

    question:
      "問題なく自己注射ができると確認でき、医師に情報提供したところ、この薬剤を継続使用することとなった。その後、7月28日に受診し、その日に薬局に処方1と同じ内容の処方箋を持って訪れた。この患者の医療費の自己負担に関する制度の内容として、適切なのはどれか。2つ選べ。",

    choices: [
    "半年（6ヶ月）の自己負担額が一定金額を超えた場合、超過分が支給される。",
    "本制度が利用可能かの判断は、独立行政法人医薬品医療機器総合機構（PMDA）が行う。",
    "この患者への支給は国民健康保険組合が行う。",
    "本制度は、対象者の年齢の上限は設定されていない。",
    "同一世帯の妻が同じ医療保険に加入しているので、自己負担を合算して本制度を利用できる。"
    ],

    answer: [3, 4],

    explanation:
      "この制度は、高額療養費制度に関する内容と考えます。高額療養費制度では、医療機関や薬局で支払った自己負担額が、同一月内に自己負担限度額を超えた場合に、超過分が支給されます。年齢による上限はなく、70歳以上でも所得区分などに応じた限度額が設定されるため、4は適切です。また、同一世帯で同じ医療保険に加入している家族の自己負担額は、一定の条件で合算できるため、5も適切です。1は「半年」ではなく、原則として「1か月」単位で判定するため誤りです。2はPMDAではなく、加入している医療保険の保険者が扱います。3も、支給を行うのはその患者が加入する保険者であり、国民健康保険組合とは限らないため適切とはいえません。"
