    question:
      "32歳女性。半年前に家族性高コレステロール血症と診断され、生活習慣の改善及び以下の処方の薬剤による治療を行っている。冠動脈疾患の既往歴はない。LDL-Cは管理目標値まで下げることができたが、本日の診察の際に患者から「妊娠の可能性がある」との報告があり、薬剤の変更が検討された。\n\n（処方）\nエゼチミブ・アトルバスタチン20 mg配合錠 1回1錠（1日1錠）\n1日1回 朝食後 28日分\n\n（検査値）\n血圧122/74 mmHg、LDL-C 80 mg/dL、HDL-C 75 mg/dL、TG（トリグリセリド）80 mg/dL\n\nこの患者に提案できる治療薬はどれか。1つ選べ。",

